insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-ob-276', 'chemistry-organic-chemistry-some-basic-principles-and-techniques', 'chemistry', 'o-Nitrophenol can be separated from p-nitrophenol by steam distillation because intramolecular hydrogen bonding makes the ortho isomer', '["ionic and involatile","more steam-volatile than the para isomer","a polymer","completely miscible with water as a salt"]'::jsonb, 1, 'Intramolecular H-bonding in o-nitrophenol reduces intermolecular association, so it is carried by steam; p-nitrophenol hydrogen-bonds intermolecularly and is less volatile.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'hard', 'purification') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
